import type { Company } from '../../../schema/company'

/**
 * Fields are the ones in the Company property table and the "Get Companies by
 * ID" example at https://www.planhat.com/developers/api/company:
 *   "owner objectId The planhat user id of the Account Manager / Success
 *    Manager to whom this company belongs."
 *   "phonePrimary string Company primary phone number."
 *   "createDate string Creation date. (Autogenerated)."
 *   example: "owner":"60ccb1c5965cc9e0f3848075", "name":"Tenet",
 *            "createDate":"2021-07-27T20:25:44.430Z",
 *            "updatedAt":"2021-08-09T16:54:17.298Z"
 *
 * Not mapped: `domains` is documented as an array ("Array of strings of company
 * domains based on endusers emails domains") whose list example holds URLs
 * ("https://google.lv"), so no single primary domain is documented. No
 * headcount field is documented, so `size` is not mapped. Both stay in
 * metadata.
 */
export interface RawPlanhatCompany {
  _id: string
  name: string
  owner?: string | null
  phonePrimary?: string
  tags?: string[]
  createDate?: string
  updatedAt?: string
  [key: string]: unknown
}

export function transformCompany(raw: RawPlanhatCompany): Company {
  return {
    id: raw._id,
    name: raw.name,
    phone: raw.phonePrimary,
    // The list example shows "owner":null for an unowned company.
    owner_id: raw.owner ?? undefined,
    tags: raw.tags,
    created_at: raw.createDate,
    updated_at: raw.updatedAt,
    metadata: raw,
  }
}

export function untransformCompany(data: Partial<Company>): Record<string, unknown> {
  const out: Record<string, unknown> = {}
  if (data.name !== undefined) out.name = data.name
  if (data.domain !== undefined) out.domain = data.domain
  if (data.phone !== undefined) out.phone = data.phone
  if (data.owner_id !== undefined) out.ownerId = data.owner_id
  if (data.tags !== undefined) out.tags = data.tags
  if (data.size !== undefined) out.employees = data.size
  return out
}
